#!/bin/bash
# 3b_drop_trimmed_metaG.sh - delete 2.trim metaG once the host-depleted copy is
# verified. Disk is the reason.
#
# A sample's trimmed metaG is removed only when ALL of these hold:
#   1. its bowtie2 log reached "overall alignment rate" (the run finished,
#      so the output is not a truncated file still being written)
#   2. filtered R1 and R2 both pass `gzip -t`
#   3. filtered R1 and R2 hold the same number of reads
#
# Deleting is still safe to get wrong: the raw reads are untouched, so the
# trimmed metaG can be regenerated by re-running trim-galore.
#
#   Usage: bash drop_trimmed_metaG.sh <config.sh> [--watch]
#
# --watch polls until every sample is done, freeing space as the filter runs.
set -uo pipefail
CONFIG=${1:?config file required}
WATCH=${2:-}
source "$CONFIG"

OUT="${HF_OUT}/filtered"; LOGS="${HF_OUT}/logs"
LEDGER="${HF_OUT}/dropped_trimmed_metaG.tsv"
[[ -s "$LEDGER" ]] || echo -e "time\tsample\tfreed_bytes\tr1_reads\tr2_reads" > "$LEDGER"

mapfile -t SAMPLES < <(ls "$TRIM_DIR"/*"${METAG_R1_SUFFIX}" 2>/dev/null | xargs -n1 basename | sed "s/${METAG_R1_SUFFIX}\$//")
[[ ${#SAMPLES[@]} -eq 0 ]] && { echo "nothing left in $TRIM_DIR"; exit 0; }

check_and_drop() {
    local s=$1
    local t1="${TRIM_DIR}/${s}${METAG_R1_SUFFIX}" t2="${TRIM_DIR}/${s}${METAG_R2_SUFFIX}"
    local f1="${OUT}/${s}${METAG_R1_SUFFIX}"     f2="${OUT}/${s}${METAG_R2_SUFFIX}"
    [[ -f "$t1" || -f "$t2" ]] || return 0          # already gone
    grep -q 'overall alignment rate' "${LOGS}/${s}.metaG.log" 2>/dev/null || return 1
    [[ -s "$f1" && -s "$f2" ]] || { echo "  [$s] FAIL: filtered output missing"; return 1; }
    gzip -t "$f1" 2>/dev/null || { echo "  [$s] FAIL: $f1 corrupt"; return 1; }
    gzip -t "$f2" 2>/dev/null || { echo "  [$s] FAIL: $f2 corrupt"; return 1; }
    local n1 n2
    n1=$(zcat "$f1" | wc -l); n2=$(zcat "$f2" | wc -l)
    [[ "$n1" == "$n2" && "$n1" -gt 0 ]] || { echo "  [$s] FAIL: R1/R2 read counts differ ($n1 vs $n2)"; return 1; }
    local freed
    freed=$(du -cb "$t1" "$t2" 2>/dev/null | tail -1 | cut -f1)
    rm -f "$t1" "$t2"
    echo -e "$(date '+%F %T')\t${s}\t${freed}\t$((n1/4))\t$((n2/4))" >> "$LEDGER"
    echo "  [$s] verified, dropped trimmed metaG ($(numfmt --to=iec "$freed"))"
    return 0
}

while :; do
    remaining=0
    for s in "${SAMPLES[@]}"; do
        [[ -f "${TRIM_DIR}/${s}${METAG_R1_SUFFIX}" ]] || continue
        check_and_drop "$s" || remaining=$((remaining+1))
    done
    [[ "$WATCH" == "--watch" ]] || break
    [[ "$remaining" -eq 0 ]] && break
    sleep 120
done

echo "[$(date '+%F %T')] done. df: $(df -h "$TRIM_DIR" | tail -1 | awk '{print $4" free ("$5" used)"}')"
